[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeWarrantyInventTableApplPriceRangeMin extends UPSPricingAttributeWarrantyInventTable implements UPSIPricingAttribute
