public str getName()
{
    return fieldPName(WarrantyInventTable, ApplicablePriceRangeMin);
}

public Set getAllowedValues()
{   
    WarrantyInventTable warrantyInventTable;
    var                 ret = new Set(Types::Real);

    while select ApplicablePriceRangeMin from warrantyInventTable
        group by ApplicablePriceRangeMin
    {
        if (!ret.in(warrantyInventTable.ApplicablePriceRangeMin))
        {
            ret.add(warrantyInventTable.ApplicablePriceRangeMin);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(WarrantyInventTable, ApplicablePriceRangeMin));
    qbr.value(queryValue(_value));
}
